register(definitionSource, execute) {
  const resolved = this.resolveDefinition(definitionSource);
  const validators = new WeakMap<object, ValidateFunction>();
  if (typeof definitionSource !== 'function') {
    validators.set(resolved.inputSchema, this.compileSchema(resolved, resolved.name));
  }
  this.tools.set(resolved.name, {definitionSource, execute, validators});
}

private compileSchema(definition: ToolDefinition, name: string): ValidateFunction {
  try {
    return ajv.compile(definition.inputSchema);
  } catch (error) {
    throw new Error(`Tool ${name} has an invalid inputSchema: ${error instanceof Error ? error.message : String(error)}`);
  }
